<?php
// Studio is a protected non-sellable location. Requests and approvals never post stock.
function studio_query($sql,$args=[]){$q=db()->prepare($sql);$q->execute($args);return $q;}
function studio_ready(){if(!array_key_exists('STUDIO_READY',$GLOBALS)){$names=db()->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$GLOBALS['STUDIO_READY']=!array_diff(['studio_requests','studio_request_lines','studio_request_events'],$names);}return $GLOBALS['STUDIO_READY'];}
function studio_install(){if(current_user()['role']!=='Admin')throw new Exception('Admin setup required.');
 db()->exec("CREATE TABLE IF NOT EXISTS studio_requests(id BIGINT AUTO_INCREMENT PRIMARY KEY,request_ref VARCHAR(100) NOT NULL UNIQUE,request_key CHAR(64) NOT NULL UNIQUE,created_by INT NOT NULL,needed_date DATE NOT NULL,session_reference VARCHAR(500) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'Pending',revision INT NOT NULL DEFAULT 1,decision TEXT NULL,approved_by INT NULL,approved_at DATETIME NULL,transferred_by INT NULL,transferred_at DATETIME NULL,handed_to VARCHAR(120) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status),INDEX(created_by)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 db()->exec("CREATE TABLE IF NOT EXISTS studio_request_lines(id BIGINT AUTO_INCREMENT PRIMARY KEY,request_id BIGINT NOT NULL,product_id INT NOT NULL,requested_qty INT NOT NULL,approved_qty INT NULL,sku_snapshot VARCHAR(120) NOT NULL,name_snapshot VARCHAR(500) NOT NULL,source_platform VARCHAR(40) NULL,non_sellable_id BIGINT NULL,UNIQUE(request_id,product_id),INDEX(product_id),INDEX(non_sellable_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 db()->exec("CREATE TABLE IF NOT EXISTS studio_request_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,request_id BIGINT NOT NULL,event_type VARCHAR(60) NOT NULL,user_id INT NOT NULL,user_name VARCHAR(120) NOT NULL,user_role VARCHAR(40) NOT NULL,details_json LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(request_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 unset($GLOBALS['STUDIO_READY']);if(!studio_ready())throw new Exception('Studio tables are incomplete.');set_setting('studio_schema_version','1');audit('Enable Studio Stocks','Studio','1','Additive request and trail tables; no stocks changed.');}
function studio_require($action=null){if(!studio_ready())throw new Exception('Ask Admin to enable Studio Stocks first.');if($action&&!can_action($action))throw new Exception('Your role cannot perform this Studio action.');}
function studio_source($r){return norm($r['condition_type']??'')==='studio display / demo'||norm($r['origin']??'')==='studio transfer';}
function studio_balance($pid,$date=null){if(!studio_ready())return 0;return (int)studio_query("SELECT COALESCE(SUM(qty),0) FROM non_sellable n WHERE n.product_id=? AND n.condition_type='Studio Display / Demo' AND n.origin='Studio Transfer' AND EXISTS(SELECT 1 FROM studio_request_lines l WHERE l.non_sellable_id=n.id) AND (? IS NULL OR n.txn_date<=?)",[(int)$pid,$date,$date])->fetchColumn();}
function studio_protect_count($id){wc_guard_count($id);$b=count_batch($id);$meta=json_decode($b['filter_json']??'{}',true)?:[];if(($meta['count_scope']??'All Conditions')==='Sellable')return;foreach(count_lines($id) as $l)if(studio_balance($l['product_id'])>0)throw new Exception('This item has protected Studio display/demo stock. Use Sellable Only for warehouse counts; Studio quantities must not be adjusted as Other Restricted.');}
function studio_request($id,$lock=false){studio_require();$r=studio_query('SELECT r.*,u.name requester_name,a.name approver_name,t.name transfer_name FROM studio_requests r LEFT JOIN users u ON u.id=r.created_by LEFT JOIN users a ON a.id=r.approved_by LEFT JOIN users t ON t.id=r.transferred_by WHERE r.id=?'.($lock?' FOR UPDATE':''),[(int)$id])->fetch();if(!$r)throw new Exception('Studio request not found.');return $r;}
function studio_lines($id){return studio_query('SELECT l.*,p.master_sku,p.name,p.active FROM studio_request_lines l JOIN products p ON p.id=l.product_id WHERE l.request_id=? ORDER BY l.id',[(int)$id])->fetchAll();}
function studio_event($id,$kind,$detail){$u=current_user();studio_query('INSERT INTO studio_request_events(request_id,event_type,user_id,user_name,user_role,details_json) VALUES(?,?,?,?,?,?)',[$id,$kind,$u['id'],$u['name'],$u['role'],json_encode($detail,JSON_THROW_ON_ERROR)]);audit($kind,'Studio Request','STR-'.$id,json_encode($detail,JSON_THROW_ON_ERROR));}
function studio_create($input){studio_require('studio_create');$key=(string)($input['request_key']??'');if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new Exception('Reopen the stock request form.');$date=process_date($input['needed_date']??'');$ref=trim((string)($input['session_reference']??''));if(mb_strlen($ref)<3||mb_strlen($ref)>500)throw new Exception('Enter a live session / demo reference (3–500 characters).');$raw=$input['items']??[];if(!is_array($raw)||!$raw||count($raw)>50)throw new Exception('Enter 1 to 50 item lines.');$lines=[];foreach($raw as $x){$sku=trim((string)($x['sku']??''));$p=studio_query('SELECT * FROM products WHERE master_sku=? AND active=1',[$sku])->fetch();if(!$p)throw new Exception('Select an active exact Master SKU: '.$sku);$qty=whole_number($x['qty']??'','Requested quantity',1);if($qty>99999999)throw new Exception('Quantity is too large.');if(isset($lines[$p['id']]))throw new Exception('Combine duplicate SKU lines.');$lines[$p['id']]=['product_id'=>(int)$p['id'],'sku'=>$p['master_sku'],'name'=>$p['name'],'qty'=>$qty];}
 return process_transaction(function()use($input,$key,$date,$ref,$lines){$old=studio_query('SELECT id,created_by FROM studio_requests WHERE request_key=?',[$key])->fetch();if($old){if((int)$old['created_by']!==current_user()['id'])throw new Exception('Request key belongs to another user.');return (int)$old['id'];}studio_query('INSERT INTO studio_requests(request_ref,request_key,created_by,needed_date,session_reference) VALUES(?,?,?,?,?)',[next_ref('STR').'-'.bin2hex(random_bytes(3)),$key,current_user()['id'],$date,$ref]);$id=(int)db()->lastInsertId();foreach($lines as $l)studio_query('INSERT INTO studio_request_lines(request_id,product_id,requested_qty,sku_snapshot,name_snapshot) VALUES(?,?,?,?,?)',[$id,$l['product_id'],$l['qty'],$l['sku'],$l['name']]);studio_event($id,'Studio stocks requested',['purpose'=>'Live Session Display & Demo','needed_date'=>$date,'session_reference'=>$ref,'items'=>array_values($lines),'stock_effect'=>'No stock change']);return $id;});}
function studio_decide($id,$input){studio_require('studio_decide');return process_transaction(function()use($id,$input){$r=studio_request($id,true);if($r['status']!=='Pending'||(int)($input['revision']??0)!==(int)$r['revision'])throw new Exception('Request already reviewed or changed. Refresh it.');$decision=$input['decision']??'';if(!in_array($decision,['Approve','Reject'],true))throw new Exception('Choose Approve or Reject.');$reason=trim((string)($input['reason']??''));if(mb_strlen($reason)>2000)throw new Exception('Decision remarks are too long.');$out=[];$total=0;$reduced=false;foreach(studio_lines($id) as $l){$qty=$decision==='Reject'?0:whole_number($input['approved'][$l['id']]??'','Approved quantity',0);if($qty>(int)$l['requested_qty'])throw new Exception('Approved quantity cannot exceed requested quantity.');if($qty&&!$l['active'])throw new Exception('An approved item is inactive.');$reduced|=$qty<(int)$l['requested_qty'];$total+=$qty;$out[]=['sku'=>$l['sku_snapshot'],'requested'=>(int)$l['requested_qty'],'approved'=>$qty];studio_query('UPDATE studio_request_lines SET approved_qty=? WHERE id=?',[$qty,$l['id']]);}if($decision==='Approve'&&!$total)throw new Exception('Approve at least one piece or reject the request.');if(($reduced||$decision==='Reject')&&mb_strlen($reason)<3)throw new Exception('Enter the reason for rejection / reduced quantity.');$status=$decision==='Approve'?'Approved':'Rejected';studio_query('UPDATE studio_requests SET status=?,decision=?,approved_by=?,approved_at=NOW(),revision=revision+1 WHERE id=?',[$status,$reason,current_user()['id'],$id]);studio_event($id,'Studio request '.$status,['items'=>$out,'remarks'=>$reason,'stock_effect'=>'No stock change']);return $status;});}
function studio_cancel($id,$input){studio_require();$r=studio_request($id);$admin=current_user()['role']==='Admin';if(!$admin&&(!can_action('studio_cancel')||(int)$r['created_by']!==current_user()['id']))throw new Exception('Only the requesting Live Producer or Admin may cancel.');$reason=process_reason($input['reason']??'');return process_transaction(function()use($id,$input,$reason,$admin){$r=studio_request($id,true);if(!in_array($r['status'],$admin?['Pending','Approved']:['Pending'],true)||(int)$r['revision']!==(int)($input['revision']??0))throw new Exception('Only an eligible untransferred current request can be cancelled.');studio_query("UPDATE studio_requests SET status='Cancelled',revision=revision+1 WHERE id=?",[$id]);studio_event($id,'Studio request Cancelled',['previous_status'=>$r['status'],'reason'=>$reason,'stock_effect'=>'No stock change']);});}
function studio_plan($id,$sources){studio_require('studio_post');$r=studio_request($id);if($r['status']!=='Approved')throw new Exception('Select an approved untransferred request.');$rows=[];$ids=array_column(studio_lines($id),'product_id');sort($ids,SORT_NUMERIC);foreach($ids as $pid)studio_query('SELECT id FROM products WHERE id=? FOR UPDATE',[$pid]);unset($GLOBALS['OM_RESERVED']);foreach(studio_lines($id) as $l){$qty=(int)$l['approved_qty'];if(!$qty)continue;$p=active_product($l['product_id']);$pl=stock_platform($sources[$l['id']]??'');check_platform_alignment($l['product_id']);om_assert_available($l['product_id'],$qty);om_assert_available($l['product_id'],$qty,$pl);$s=stock_row($l['product_id']);$rows[]=['line_id'=>(int)$l['id'],'pid'=>(int)$l['product_id'],'sku'=>$p['master_sku'],'name'=>$p['name'],'qty'=>$qty,'platform'=>$pl,'source_before'=>platform_qty($pl,$l['product_id']),'available'=>om_available($l['product_id'],$pl),'sellable_before'=>(int)$s['current'],'studio_before'=>studio_balance($l['product_id']),'physical_before'=>(int)$s['physical']];}if(!$rows)throw new Exception('No approved quantity.');$p=['id'=>(int)$id,'revision'=>(int)$r['revision'],'rows'=>$rows];$p['digest']=hash('sha256',json_encode($p));return $p;}
function studio_post($id,$input){studio_require('studio_post');if(empty($input['physical_ack']))throw new Exception('Confirm the actual physical handover.');$handed=trim((string)($input['handed_to']??''));if(mb_strlen($handed)<3||mb_strlen($handed)>120)throw new Exception('Enter the name of the person receiving the Studio items.');return process_transaction(function()use($id,$input,$handed){$r=studio_request($id,true);$p=studio_plan($id,$input['sources']??[]);if(!hash_equals($p['digest'],(string)($input['digest']??'')))throw new Exception('Stock / request changed. Review the latest transfer effects again.');$date=date('Y-m-d');require_open_inventory_date($date);$changes=[];foreach($p['rows'] as $l){$note='Studio live session display/demo; '.$r['session_reference'].'; Handed to '.$handed;studio_query("INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id) VALUES(?,?,?,?,?,'Studio Display / Demo','Transfer to Studio','In Studio','Studio Transfer',1,?,?)",[$date,$l['platform'],$r['request_ref'],$l['pid'],$l['qty'],$note,current_user()['id']]);$ns=(int)db()->lastInsertId();change_platform_stock($l['platform'],$l['pid'],-$l['qty'],$r['request_ref'],$date);check_platform_alignment($l['pid']);studio_query('UPDATE studio_request_lines SET source_platform=?,non_sellable_id=? WHERE id=?',[$l['platform'],$ns,$l['line_id']]);$after=stock_row($l['pid']);if((int)$after['physical']!==$l['physical_before'])throw new Exception('Physical quantity reconciliation failed.');$changes[]=$l+['source_after'=>$l['source_before']-$l['qty'],'sellable_after'=>$l['sellable_before']-$l['qty'],'studio_after'=>studio_balance($l['pid']),'physical_after'=>(int)$after['physical'],'non_sellable_id'=>$ns];}studio_query("UPDATE studio_requests SET status='Transferred',transferred_by=?,transferred_at=NOW(),handed_to=?,revision=revision+1 WHERE id=?",[current_user()['id'],$handed,$id]);studio_event($id,'Studio transfer posted',['purpose'=>'Live Session Display & Demo','handed_to'=>$handed,'transfer_date'=>$date,'items'=>$changes,'stock_effect'=>'Sellable decreases; Studio increases; total physical unchanged']);unset($GLOBALS['OM_RESERVED']);return $p;});}
